-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["02231303e630809e"] = { "Tra questi, il martello da fabbro che mi regalò mio padre. Da giovane non ci credevo, ma lui mi ha sempre detto che il martello era incantato, ed è l'ultimo ricordo che avevo di lui prima che venisse ucciso dal Flagello.\n\nPortami il mio martello, {name}, così potrò usarlo per incanalare la mia passione. Se è davvero incantato, non potrà che aiutare entrambi.\n\nL'ho lasciato nelle stalle del cortile principale della fortezza. A meno che le creature che ci vivono non si siano messe a fare i fabbri, mi aspetto che sia ancora lì per terra.", "." },
  ["023901c8817573e4"] = { "Per aiutare l'arcimago a compiere la sua missione, Ner'zhul lasciò intatta l'umanità di Kel'Thuzad. L'anziano ma ancora carismatico mago ebbe il compito di usare i suoi poteri di illusione e di persuasione per cullare le masse oppresse e diseredate di Lordaeron in uno stato di fiducia e di fede. Poi, una volta conquistata la loro attenzione, avrebbe offerto loro una nuova visione di ciò che la società poteva essere - e una nuova guida da chiamare re.", "." },
  ["0250cbd59e931608"] = { "Avanzai lentamente, il fucile alzato. Avevo condotto questi coraggiosi cacciatori verso la morte. Sarei morto difendendoli. I Lashtail Raptor sono particolarmente feroci, noti per la loro implacabile sete di sangue. Erano molti più di noi. Ma che io sia dannato se li avrei lasciati uccidere me e i miei compagni senza prima versare un po' del loro sangue.", "." },
  ["02674fef1eff698a"] = { "Onorevoli colleghi e cercatori della verità\n\nGli scavi del sito proseguono, ma sono rallentati dai trogg citati nel mio ultimo rapporto. Sono fiducioso che si possa averne ragione, anche se alcuni di questi trogg sono più aggressivi del solito.\n\nDi recente sono stati rinvenuti altri manufatti, ma in tutti i casi tranne uno (di cui parlerò più avanti) le ultime scoperte sono dello stesso livello delle precedenti: interessanti, se non illuminanti.", "." },
  ["027ff3f48a56c60b"] = { "Tuttavia, all'insaputa dell'⟦Alliance=Alleanza⟧, una grande forza di orchi vagava ancora libera nelle lande settentrionali di Khaz Modan. Il clan delle Fauci di Drago, guidato dal famigerato stregone Nekros, usava un antico manufatto noto come Demon Soul per controllare la Regina dei Draghi, Alexstrasza, e il suo stormo. Con la Regina dei Draghi come ostaggio, Nekros mise insieme un esercito segreto nell'abbandonata, e secondo alcuni maledetta, roccaforte dei Granmartello, Grim Batol.", "." },
  ["028e256ffb1f45a3"] = { "Gli Umani presero di mira la pantera mentre correva lungo il limitare del bosco. Le canne dei loro fucili si muovevano in perfetto parallelo. Barnil mi lanciò un'occhiata insistente, ma io scossi la testa. Questa caccia era per gli Umani, non per Barnil o per me. Erlgadin sparò un colpo fragoroso, mancando del tutto la pantera. A quanto pare non era preparato al violento rinculo del fucile.", "." },
  ["02f42c2d96187f63"] = { "Certa che il suo bambino fosse sano e forte, Aegwynn portò il giovane Medivh alla corte di Azeroth e lo lasciò lì, perché fosse cresciuto dal padre mortale e dalla sua gente. Poi si inoltrò nelle terre selvagge e si preparò a passare a qualunque aldilà la attendesse. Medivh crebbe forte e robusto, senza avere alcuna idea del potere che la sua eredità di Tirisfal racchiudeva.", "." },
})
